<script setup>
import {ref,watch} from 'vue'
import {RouterLink,RouterView,useRoute} from 'vue-router'
import {site} from './data/site.js'
import {t,language} from './data/i18n.js'
const saved=(()=>{try{return localStorage.getItem('arvak-theme')}catch{return null}})()
const theme=ref(saved==='light'||saved==='dark'?saved:(window.matchMedia?.('(prefers-color-scheme: light)').matches?'light':'dark'))
const menuOpen=ref(false),route=useRoute()
watch(theme,v=>{document.documentElement.dataset.theme=v;try{localStorage.setItem('arvak-theme',v)}catch{}},{immediate:true})
watch(()=>route.fullPath,()=>{menuOpen.value=false})
</script>
<template><div class="site-shell"><a href="#main" class="skip-link">{{t('skip')}}</a><header class="site-header"><div class="container header-inner"><RouterLink class="brand" to="/" aria-label="Arvak Labs"><span class="brand-glyph" aria-hidden="true">A<span>✦</span></span><span>ARVAK <b>LABS</b><small>INDEPENDENT DIGITAL STUDIO</small></span></RouterLink><nav :class="['nav',{'nav-open':menuOpen}]" id="main-nav" :aria-label="t('menu')"><RouterLink to="/">{{t('home')}}</RouterLink><RouterLink to="/explorar">{{t('explore')}}</RouterLink><RouterLink to="/jogos">{{t('games')}}</RouterLink><RouterLink to="/sobre">{{t('about')}}</RouterLink><RouterLink to="/portfolio">{{t('portfolio')}}</RouterLink><a :href="site.github" target="_blank" rel="noopener noreferrer">GitHub ↗</a></nav><div class="header-tools"><label class="language-select"><span class="visually-hidden">{{t('language')}}</span><select v-model="language" :aria-label="t('language')"><option value="en">EN</option><option value="pt-BR">PT-BR</option></select></label><button class="icon-btn" type="button" @click="theme=theme==='dark'?'light':'dark'" :aria-label="theme==='dark'?t('themeLight'):t('themeDark')">{{theme==='dark'?'☀':'☾'}}</button><button class="icon-btn menu-button" type="button" :aria-expanded="menuOpen" aria-controls="main-nav" @click="menuOpen=!menuOpen" :aria-label="t('menu')">{{menuOpen?'✕':'☰'}}</button></div></div></header><main id="main"><RouterView/></main><footer class="site-footer"><div class="container footer-layout"><div><div class="footer-brand">ARVAK <b>LABS</b><span> ✦</span></div><p>{{t('slogan')}}</p></div><div class="footer-links"><RouterLink to="/explorar">{{t('projects')}}</RouterLink><RouterLink to="/sobre">{{t('about')}}</RouterLink><RouterLink to="/portfolio">{{t('portfolio')}}</RouterLink><a :href="site.github" target="_blank" rel="noopener noreferrer">GitHub ↗</a></div></div><div class="container footer-bottom"><span>© {{new Date().getFullYear()}} Arvak Labs</span><span>{{t('made')}}</span></div></footer></div></template>
